//! `SourceService::rebuild_index` and `Store::rebuild_index` (lot 5.3) against the scenarios that
//! the .NET `SourceService.RebuildIndex` played on the real `SqliteStore`
//! (`rust/tests/golden/index-rebuild.json`, regenerated by `rust/tools/index-rebuild-oracle`):
//! each scenario is replayed in a new instance, with the real file reader wrapped to record the
//! paths it reads, or to fail on one of them. After each rebuild, the answer, the paths read, the
//! names of the projection files and the rows of `records`, `history` and `search` (through the
//! SQL recorded by the oracle) are compared.
//!
//! The reader failure is the `IOException` of the oracle: the Rust reader answers
//! `invalid_storage_or_path`, what the command line prints for it. A source without path (altered
//! base only) is the `NullReferenceException` of .NET, thrown by its reader; the Rust service
//! answers `invalid_storage_or_path` before reading (`PARITY.md`, Écarts assumés).

use std::cell::RefCell;
use std::collections::HashSet;
use std::fs;
use std::path::{Path, PathBuf};

use serde_json::{Value, json};
use sermofur_core::discovery::expand_short_names;
use sermofur_core::error::{Result, SermofurError};
use sermofur_core::memory::MemoryContext;
use sermofur_core::records::{DotNetEnum, MemoryRecord, Scope, ScopeKind, read};
use sermofur_core::source_service::{SourceService, file_reader};
use sermofur_core::sources::SourceSnapshot;
use sermofur_core::store::Store;
use uuid::Uuid;

/// A folder under the temporary directory, removed on drop.
struct Folder(PathBuf);

impl Drop for Folder {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.0);
    }
}

/// An instance: the store is declared first, so its connection closes before the folder goes.
struct Instance {
    store: Store,
    root: PathBuf,
    _folder: Folder,
}

fn instance() -> Instance {
    let temp = std::env::temp_dir();
    let base = if cfg!(windows) {
        expand_short_names(&temp)
    } else {
        fs::canonicalize(temp).expect("temp")
    };
    let root = base.join(format!("sermofur-rebuild-{}", Uuid::new_v4().simple()));
    fs::create_dir_all(root.join(".sermofur")).expect("marker");
    let folder = Folder(root.clone());
    let id = Uuid::parse_str("11111111-2222-4333-8444-555555555555").expect("GUID");
    sermofur_core::schema::create_database(&root.join(".sermofur").join("memory.db"), id)
        .expect("created");
    let store = Store::open(&root, id, false).expect("opened");
    Instance {
        store,
        root,
        _folder: folder,
    }
}

fn text(value: &Value) -> &str {
    value.as_str().expect("string")
}

/// The answer as the oracle recorded it; an exception of .NET is the refusal the command line
/// prints for it.
fn expected_answer(answer: &Value) -> Value {
    match answer["exception"].as_str() {
        Some("IOException" | "NullReferenceException") => json!({
            "code": "invalid_storage_or_path",
            "message": "Invalid path or data; run doctor.",
            "exitCode": 3,
        }),
        Some(other) => panic!("unexpected exception {other}"),
        None => answer.clone(),
    }
}

fn answer<T: serde::Serialize>(result: Result<T>) -> Value {
    match result {
        Ok(value) => Value::String(
            sermofur_core::json::to_string(&value)
                .expect("JSON")
                .replace("\r\n", "\n"),
        ),
        Err(error) => json!({
            "code": error.code,
            "message": error.message,
            "exitCode": error.exit_code,
        }),
    }
}

fn rows(database: &Path, sql: &str) -> Value {
    let raw = rusqlite::Connection::open(database).expect("raw");
    let mut statement = raw.prepare(sql).expect("prepared");
    let count = statement.column_count();
    let rows: Vec<Value> = statement
        .query_map([], |row| {
            let mut cells = Vec::new();
            for i in 0..count {
                cells.push(match row.get_ref(i)? {
                    rusqlite::types::ValueRef::Null => Value::Null,
                    rusqlite::types::ValueRef::Integer(n) => json!(n),
                    rusqlite::types::ValueRef::Text(t) => json!(String::from_utf8_lossy(t)),
                    other => json!(format!("{other:?}")),
                });
            }
            Ok(Value::Array(cells))
        })
        .expect("query")
        .collect::<rusqlite::Result<_>>()
        .expect("rows");
    Value::Array(rows)
}

fn projections(root: &Path) -> Value {
    let mut names: Vec<String> = fs::read_dir(root.join(".sermofur").join("records"))
        .map(|entries| {
            entries
                .map(|e| e.expect("entry").file_name().to_string_lossy().into_owned())
                .collect()
        })
        .unwrap_or_default();
    names.sort();
    json!(names)
}

/// The rows that the oracle gives on this system. The source `.sermofur/memory.db` is the
/// database itself, read inside the write transaction of the rebuild, while SQLite holds its
/// `fcntl` RESERVED lock. Both readers take a shared `flock` (`FileStream` on Unix, `read_bounded`).
/// On macOS, `flock` and `fcntl` locks conflict, so the oracle there would read it as unreadable
/// (deduced from its code, see `PARITY.md`), not as the binary of the golden file recorded on
/// Windows. Its rows are left out on macOS only.
fn platform_rows(rows: Value) -> Value {
    if !cfg!(target_os = "macos") {
        return rows;
    }
    let database = r#""relativePath":".sermofur/memory.db""#;
    Value::Array(
        rows.as_array()
            .expect("rows")
            .iter()
            .filter(|row| !row.to_string().replace('\\', "").contains(database))
            .cloned()
            .collect(),
    )
}

fn hex(text: &str) -> Vec<u8> {
    (0..text.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&text[i..i + 2], 16).expect("hex"))
        .collect()
}

#[test]
fn the_rebuild_is_the_one_of_the_dotnet_service() {
    let path = format!(
        "{}/../../tests/golden/index-rebuild.json",
        env!("CARGO_MANIFEST_DIR")
    );
    let golden: Value =
        serde_json::from_str(&fs::read_to_string(path).expect("golden file")).expect("JSON");
    let mut mismatches = Vec::new();
    let mut rebuilds = 0;
    for scenario in golden["scenarios"].as_array().expect("scenarios") {
        let name = text(&scenario["name"]);
        let mut instance = instance();
        let root = instance.root.clone();
        let database = root.join(".sermofur").join("memory.db");
        for (index, step) in scenario["steps"]
            .as_array()
            .expect("steps")
            .iter()
            .enumerate()
        {
            let at = |path: &Value| root.join(text(path));
            match text(&step["op"]) {
                "addScope" => {
                    fs::create_dir_all(at(&step["path"])).expect("scope folder");
                    let kind = ScopeKind::NAMES
                        .iter()
                        .find(|(n, _, _)| *n == text(&step["kind"]))
                        .map(|(_, _, m)| *m)
                        .expect("scope kind");
                    let scope = Scope {
                        id: text(&step["id"]).to_owned(),
                        kind,
                        parent_id: Some(text(&step["parent"]).to_owned()),
                        relative_path: Some(text(&step["path"]).to_owned()),
                    };
                    instance
                        .store
                        .add_scope(&scope, |_| Ok(()))
                        .expect("scope added");
                }
                "create" => {
                    let record: MemoryRecord =
                        read(text(&step["payload"]), &|_| 0).expect("payload");
                    instance
                        .store
                        .create_record(&record, None)
                        .expect("created");
                }
                "file" => {
                    let file = at(&step["path"]);
                    fs::create_dir_all(file.parent().expect("parent")).expect("folders");
                    fs::write(file, text(&step["text"])).expect("file");
                }
                "bytes" => fs::write(at(&step["path"]), hex(text(&step["hex"]))).expect("file"),
                "fill" => {
                    let count =
                        usize::try_from(step["count"].as_u64().expect("count")).expect("small");
                    fs::write(at(&step["path"]), vec![b'a'; count]).expect("file");
                }
                "mkdir" => fs::create_dir_all(at(&step["path"])).expect("folder"),
                "rmdir" => fs::remove_dir_all(at(&step["path"])).expect("folder removed"),
                "remove" => fs::remove_file(at(&step["path"])).expect("file removed"),
                "sql" => {
                    rusqlite::Connection::open(&database)
                        .expect("raw")
                        .execute(text(&step["sql"]), [])
                        .expect("tampered");
                }
                "rebuild" => {
                    rebuilds += 1;
                    let failing = step["failing"].as_str();
                    let reads = RefCell::new(Vec::new());
                    let reader = |root: &Path, relative: &str| -> Result<SourceSnapshot> {
                        reads.borrow_mut().push(relative.to_owned());
                        if Some(relative) == failing {
                            // The `IOException("simulated read failure")` of the oracle.
                            return Err(SermofurError::new(
                                "invalid_storage_or_path",
                                "Invalid path or data; run doctor.",
                                3,
                            ));
                        }
                        file_reader(root, relative)
                    };
                    let context = MemoryContext {
                        root: root.clone(),
                        scope_id: text(&step["scope"]).to_owned(),
                        visible: HashSet::new(),
                    };
                    let actual = answer(
                        SourceService::new(&mut instance.store, &reader, &context)
                            .and_then(|mut service| service.rebuild_index()),
                    );
                    let label = format!("{name} step {index}");
                    let expected = expected_answer(&step["answer"]);
                    if actual != expected {
                        mismatches.push(format!(
                            "{label} answer:\n  expected {expected}\n  got      {actual}"
                        ));
                    }
                    // .NET reads a source without path (null) before failing; Rust refuses it
                    // before reading.
                    let expected_reads: Vec<Value> = step["reads"]
                        .as_array()
                        .expect("reads")
                        .iter()
                        .filter(|read| !read.is_null())
                        .cloned()
                        .collect();
                    let actual_reads = json!(*reads.borrow());
                    if actual_reads != Value::Array(expected_reads.clone()) {
                        mismatches.push(format!(
                            "{label} reads:\n  expected {expected_reads:?}\n  got      {actual_reads}"
                        ));
                    }
                    let actual_projections = projections(&root);
                    if actual_projections != step["projections"] {
                        mismatches.push(format!(
                            "{label} projections:\n  expected {}\n  got      {actual_projections}",
                            step["projections"]
                        ));
                    }
                    for table in step["tables"].as_array().expect("tables") {
                        let sql = text(&table["sql"]);
                        let actual = platform_rows(rows(&database, sql));
                        let expected = platform_rows(table["rows"].clone());
                        if actual != expected {
                            mismatches.push(format!(
                                "{label} {sql}:\n  expected {expected}\n  got      {actual}"
                            ));
                        }
                    }
                }
                other => panic!("unknown step {other}"),
            }
        }
    }
    eprintln!("index rebuild: {rebuilds} rebuilds compared");
    assert_eq!(rebuilds, 18, "rebuilds");
    assert!(mismatches.is_empty(), "{}", mismatches.join("\n"));
}
